import{generate,validate,createTraining,step,fitClassical,score,evaluate,exportModel,wave}from './hidden-core.mjs';
self.onmessage=({data:c})=>{try{validate(c);const experiment=generate(c),fit=fitClassical(experiment.obs,c.noise),ex=createTraining(experiment.obs,c.seed);const start=performance.now();for(let i=0;i<c.steps;i++){const losses=step(ex);if(i%100===99)self.postMessage({progress:i+1,losses});}const model=exportModel(ex,fit,c),metrics={nn:score((x,t)=>evaluate(ex.nn.p,x,t).u,experiment.truth),pinn:score((x,t)=>evaluate(ex.pinn.p,x,t).u,experiment.truth),classical:score((x,t)=>wave(x,t,fit.v,fit.D),experiment.truth)};if(!Object.values(metrics).every(m=>Number.isFinite(m.forecastRMSE)))throw Error('Training diverged. Try another seed or fewer steps.');self.postMessage({done:true,model,fit,metrics,truth:experiment.truth,elapsed:(performance.now()-start)/1000});}catch(e){self.postMessage({error:e.message});}};
